src/PoolFees.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {Currency} from "v4-core/src/types/Currency.sol";
import {BalanceDelta} from "v4-core/src/types/BalanceDelta.sol";
import {ModifyLiquidityParams} from "v4-core/src/types/PoolOperation.sol";
import {LaunchFees} from "./LaunchFees.sol";

/// @title The LP fees of the positions a factory seeded, claimable by anyone
/// @notice A factory owns the liquidity it seeds, so the fees that liquidity earns accrue to the
/// factory. `claimFees` collects them for one launch and splits them: `REQUESTER_BPS` to the
/// launch's requester (the wallet that paid for it, or whoever it handed the share to) and the rest
/// to the network's recipient in `LaunchFees`, read at payout, so moving that recipient moves every
/// pool's share at once. Anyone may call it; nobody can send the fees anywhere else.
///
/// @dev Payouts are attempted, not assumed. A recipient that refuses a payment (a contract without
/// `receive`, a token that blocks it) leaves the amount owed to that same address, to be paid by
/// `withdraw` once it can take it, rather than reverting the claim and holding the other party's
/// share hostage. The principal is never touched: the only liquidity change is a zero one, which v4
/// treats as collecting.
abstract contract PoolFees {
    error NoPosition(uint64 launchNumber);
    error NotRequester(uint64 launchNumber);
    error ZeroRequester();
    error ClaimInProgress();
    error UnexpectedClaim();
    error HookTookFees(int128 amount0, int128 amount1);

    event PositionOpened(uint64 indexed launchNumber, address indexed requester, int24 tickLower, int24 tickUpper);
    event RequesterChanged(uint64 indexed launchNumber, address indexed previous, address indexed next);
    event FeesClaimed(uint64 indexed launchNumber, address indexed caller, uint256 amount0, uint256 amount1);
    event FeesOwed(address indexed account, Currency indexed currency, uint256 amount);
    event FeesPaid(address indexed account, Currency indexed currency, uint256 amount);

    /// @notice One launch's seeded position and who shares its fees.
    struct Position {
        PoolKey key;
        int24 tickLower;
        int24 tickUpper;
        /// @dev Zero for a launch nobody paid for: its fees all go to the network.
        address requester;
    }

    /// @notice The network's fee recipient, read at every payout.
    LaunchFees public immutable fees;

    mapping(uint64 launchNumber => Position) internal positions;
    /// @notice What a payout could not deliver yet, by the address it belongs to and the currency.
    mapping(address account => mapping(Currency currency => uint256)) public owed;
    /// @notice The network's share not yet paid out, by currency: it belongs to whoever `fees` names when it is paid.
    mapping(Currency currency => uint256) public networkOwed;

    /// @dev The launch a claim is collecting, for the unlock callback; `inClaim` because launch 0 is a number too.
    uint64 private claiming;
    bool private inClaim;

    constructor(LaunchFees fees_) {
        fees = fees_;
    }

    /// @dev The pool manager the factory seeds through; the only caller `unlockCallback` answers.
    function _manager() internal view virtual returns (IPoolManager);

    /// @notice A launch's pool, range and requester.
    function positionOf(uint64 launchNumber)
        external
        view
        returns (PoolKey memory key, int24 tickLower, int24 tickUpper, address requester)
    {
        Position storage p = positions[launchNumber];
        return (p.key, p.tickLower, p.tickUpper, p.requester);
    }

    /// @notice Hands the requester's share of a launch's future fees to another address. Only the
    /// current holder can; what was already paid or owed stays with the address it was owed to.
    function setRequester(uint64 launchNumber, address next) external {
        Position storage p = positions[launchNumber];
        if (p.requester == address(0) || msg.sender != p.requester) revert NotRequester(launchNumber);
        if (next == address(0)) revert ZeroRequester();
        emit RequesterChanged(launchNumber, p.requester, next);
        p.requester = next;
    }

    /// @notice Collects one launch's accrued LP fees and pays both shares. Anyone may call it.
    function claimFees(uint64 launchNumber) external returns (uint256 amount0, uint256 amount1) {
        Position storage p = positions[launchNumber];
        if (p.tickLower == p.tickUpper) revert NoPosition(launchNumber);
        if (inClaim) revert ClaimInProgress();
        (claiming, inClaim) = (launchNumber, true);
        (amount0, amount1) = abi.decode(_manager().unlock(abi.encode(launchNumber)), (uint256, uint256));
        (claiming, inClaim) = (0, false);
        emit FeesClaimed(launchNumber, msg.sender, amount0, amount1);

        Currency c0 = p.key.currency0;
        Currency c1 = p.key.currency1;
        address requester = p.requester;
        _split(requester, c0, amount0);
        _split(requester, c1, amount1);
        if (requester != address(0)) {
            _payAccount(requester, c0);
            _payAccount(requester, c1);
        }
        _payNetwork(c0);
        _payNetwork(c1);
    }

    /// @notice Pays an account what an earlier payout could not. Anyone may call it; it pays only `account`.
    function withdraw(address account, Currency currency) external {
        _payAccount(account, currency);
    }

    /// @notice Pays the network's owed share in `currency` to the current recipient. Anyone may call it.
    function withdrawNetwork(Currency currency) external {
        _payNetwork(currency);
    }

    /// @dev Whether an unlock callback is a claim's, which the factory answers with `_collect`.
    function _claiming() internal view returns (bool) {
        return inClaim;
    }

    /// @dev Inside the pool manager's unlock: a zero liquidity change on the seeded position, which
    /// v4 answers with the fees accrued, taken here. A hook may adjust that delta; one that would
    /// have the position pay is refused rather than paid.
    function _collect(bytes calldata data) internal returns (bytes memory) {
        uint64 launchNumber = abi.decode(data, (uint64));
        if (launchNumber != claiming) revert UnexpectedClaim();
        Position storage p = positions[launchNumber];
        IPoolManager manager = _manager();
        (BalanceDelta delta,) = manager.modifyLiquidity(
            p.key,
            ModifyLiquidityParams({tickLower: p.tickLower, tickUpper: p.tickUpper, liquidityDelta: 0, salt: bytes32(0)}),
            ""
        );
        int128 a0 = delta.amount0();
        int128 a1 = delta.amount1();
        if (a0 < 0 || a1 < 0) revert HookTookFees(a0, a1);
        if (a0 > 0) manager.take(p.key.currency0, address(this), uint128(a0));
        if (a1 > 0) manager.take(p.key.currency1, address(this), uint128(a1));
        return abi.encode(uint256(uint128(a0)), uint256(uint128(a1)));
    }

    /// @dev Records a launch's seeded position, called once as the factory seeds it.
    function _openPosition(uint64 launchNumber, PoolKey memory key, int24 tickLower, int24 tickUpper, address requester)
        internal
    {
        positions[launchNumber] = Position(key, tickLower, tickUpper, requester);
        emit PositionOpened(launchNumber, requester, tickLower, tickUpper);
    }

    function _split(address requester, Currency currency, uint256 amount) private {
        if (amount == 0) return;
        uint256 share = requester == address(0) ? 0 : (amount * fees.REQUESTER_BPS()) / 10_000;
        if (share > 0) owed[requester][currency] += share;
        networkOwed[currency] += amount - share;
    }

    function _payAccount(address account, Currency currency) private {
        uint256 amount = owed[account][currency];
        if (amount == 0) return;
        owed[account][currency] = 0;
        if (_send(currency, account, amount)) {
            emit FeesPaid(account, currency, amount);
        } else {
            owed[account][currency] = amount;
            emit FeesOwed(account, currency, amount);
        }
    }

    function _payNetwork(Currency currency) private {
        uint256 amount = networkOwed[currency];
        if (amount == 0) return;
        address recipient = fees.feeRecipient();
        networkOwed[currency] = 0;
        if (_send(currency, recipient, amount)) {
            emit FeesPaid(recipient, currency, amount);
        } else {
            networkOwed[currency] = amount;
            emit FeesOwed(recipient, currency, amount);
        }
    }

    /// @dev A payment that reports failure instead of reverting: native ETH by call, a token by
    /// `transfer`, accepting a token that returns nothing and refusing one that returns false. At
    /// most one word of what the callee returns is copied, so a recipient or token answering with a
    /// huge revert cannot spend the claimer's gas on the copy.
    function _send(Currency currency, address to, uint256 amount) private returns (bool ok) {
        if (currency.isAddressZero()) {
            assembly ("memory-safe") {
                ok := call(gas(), to, amount, 0, 0, 0, 0)
            }
            return ok;
        }
        address token = Currency.unwrap(currency);
        if (token.code.length == 0) return false;
        bytes memory data = abi.encodeCall(IERC20.transfer, (to, amount));
        uint256 size;
        uint256 word;
        assembly ("memory-safe") {
            ok := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0)
            size := returndatasize()
            if gt(size, 0x1f) {
                returndatacopy(0, 0, 0x20)
                word := mload(0)
            }
        }
        return ok && (size == 0 || (size >= 32 && word == 1));
    }
}

src/HookFlags.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title The 14 bits a v4 hook address has to carry
/// @notice Uniswap v4 encodes a hook's permissions in the low 14 bits of its address, and
/// `PoolManager` rejects a hook whose address does not match what `getHookPermissions` reports. That
/// makes this bit layout load-bearing in three places at once: the deployer mines a CREATE2 salt
/// against it, the factory checks it on chain, and the admission gate compares it to what the
/// attested bytecode declares.
///
/// @dev Written down once, here, because three implementations of one bit layout is three chances
/// for one of them to differ — and a wrong bit produces an address the pool manager refuses, after
/// the gas is spent. `HookFlags.t.sol` asserts every constant below equals the one v4 itself
/// declares, so a version bump that renumbered them would fail our build rather than a mainnet
/// transaction.
library HookFlags {
    uint160 internal constant ALL = uint160((1 << 14) - 1);

    uint160 internal constant BEFORE_INITIALIZE = 1 << 13;
    uint160 internal constant AFTER_INITIALIZE = 1 << 12;
    uint160 internal constant BEFORE_ADD_LIQUIDITY = 1 << 11;
    uint160 internal constant AFTER_ADD_LIQUIDITY = 1 << 10;
    uint160 internal constant BEFORE_REMOVE_LIQUIDITY = 1 << 9;
    uint160 internal constant AFTER_REMOVE_LIQUIDITY = 1 << 8;
    uint160 internal constant BEFORE_SWAP = 1 << 7;
    uint160 internal constant AFTER_SWAP = 1 << 6;
    uint160 internal constant BEFORE_DONATE = 1 << 5;
    uint160 internal constant AFTER_DONATE = 1 << 4;
    uint160 internal constant BEFORE_SWAP_RETURN_DELTA = 1 << 3;
    uint160 internal constant AFTER_SWAP_RETURN_DELTA = 1 << 2;
    uint160 internal constant AFTER_ADD_LIQUIDITY_RETURN_DELTA = 1 << 1;
    uint160 internal constant AFTER_REMOVE_LIQUIDITY_RETURN_DELTA = 1 << 0;

    /// @notice The permission bits an address actually carries.
    function flagsOf(address hook) internal pure returns (uint160) {
        return uint160(hook) & ALL;
    }

    /// @notice Whether an address declares exactly these permissions and no others.
    /// @dev Equality rather than a mask test. A hook whose address carries a bit its implementation
    /// does not handle is called for a callback it will revert on, which takes the pool with it.
    function matches(address hook, uint160 flags) internal pure returns (bool) {
        return flagsOf(hook) == (flags & ALL);
    }
}

src/LaunchFees.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Ownable, Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

/// @title What launch pools charge, where the network's share of it goes, and the network's treasury
/// @notice One per chain. The factories read the recipient at the moment fees are paid out, so
/// changing it here moves the network's share of every pool they ever opened, past and future,
/// without touching a single pool. They read `poolFee` as they open a pool: a pool's fee is fixed
/// when it is created, so a new fee applies to the pools opened after it.
/// @dev The split itself is not here and cannot be changed: a requester was promised
/// `REQUESTER_BPS` of their pool's fees when they paid, and an owner able to lower it would make
/// that promise worth nothing. Only the recipient of the rest moves.
contract LaunchFees is Ownable2Step {
    error ZeroRecipient();
    error ZeroTreasury();
    error InvalidPoolFee(uint24 fee);

    event FeeRecipientChanged(address indexed previous, address indexed next);
    event PoolFeeChanged(uint24 previous, uint24 next);
    event TreasuryChanged(address indexed previous, address indexed next);

    /// @notice The requester's share of a pool's LP fees: 80%, which is 1% of volume at a 1.25% fee.
    uint16 public constant REQUESTER_BPS = 8000;

    /// @notice The highest pool fee the owner may set, in v4's hundredths of a basis point: 10%.
    uint24 public constant MAX_POOL_FEE = 100_000;

    /// @notice The LP fee a project factory opens its pools at, in hundredths of a basis point
    /// (12_500 is 1.25%). Hook launches keep the fee their hook's launch sets.
    uint24 public poolFee;

    /// @notice Receives the network's share: what the requester's share leaves, and all of a pool
    /// opened with no requester.
    address public feeRecipient;
    /// @notice Where unclaimed contributor rewards go once a round's year is up, and the requester's
    /// share of a launch nobody paid for. Read when it is used, like `feeRecipient`, so moving it
    /// here moves it for every distributor and launch the factories ever made.
    address public treasury;

    constructor(address owner_, address feeRecipient_, address treasury_, uint24 poolFee_) Ownable(owner_) {
        if (feeRecipient_ == address(0)) revert ZeroRecipient();
        if (treasury_ == address(0)) revert ZeroTreasury();
        if (poolFee_ == 0 || poolFee_ > MAX_POOL_FEE) revert InvalidPoolFee(poolFee_);
        feeRecipient = feeRecipient_;
        treasury = treasury_;
        poolFee = poolFee_;
        emit FeeRecipientChanged(address(0), feeRecipient_);
        emit TreasuryChanged(address(0), treasury_);
        emit PoolFeeChanged(0, poolFee_);
    }

    /// @notice Moves the network's share, for every pool at once, from the next payout on.
    function setFeeRecipient(address next) external onlyOwner {
        if (next == address(0)) revert ZeroRecipient();
        emit FeeRecipientChanged(feeRecipient, next);
        feeRecipient = next;
    }

    /// @notice Sets the fee the next project pools open at. Pools already open keep theirs.
    function setPoolFee(uint24 next) external onlyOwner {
        if (next == 0 || next > MAX_POOL_FEE) revert InvalidPoolFee(next);
        emit PoolFeeChanged(poolFee, next);
        poolFee = next;
    }

    /// @notice Moves the treasury, for every distributor and launch at once, from its next use on.
    function setTreasury(address next) external onlyOwner {
        if (next == address(0)) revert ZeroTreasury();
        emit TreasuryChanged(treasury, next);
        treasury = next;
    }
}

src/LaunchFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {IHooks} from "v4-core/src/interfaces/IHooks.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {Currency} from "v4-core/src/types/Currency.sol";
import {BalanceDelta} from "v4-core/src/types/BalanceDelta.sol";
import {ModifyLiquidityParams} from "v4-core/src/types/PoolOperation.sol";
import {HookFlags} from "./HookFlags.sol";
import {LaunchRegistry} from "./LaunchRegistry.sol";
import {MerkleDistributor} from "./MerkleDistributor.sol";
import {LaunchFees} from "./LaunchFees.sol";
import {PoolFees} from "./PoolFees.sol";

/// @title The whole launch, in one transaction
/// @notice Deploys the token and the hook at deterministic addresses, splits the supply per policy,
/// initialises the pool, seeds it, funds the contributor distributor, and writes the public record —
/// all or nothing.
///
/// @dev Atomicity buys three separate things, and the third is the one that is easy to give away
/// later for convenience:
///
/// 1. Crash safety. There is no half-launch to reason about, so a deployer killed mid-flight has
///    either done nothing or done everything.
/// 2. MEV safety. Nobody can trade between `initialize` and the first liquidity, because there is no
///    between. Splitting these into two transactions hands the first trade to whoever is watching
///    the mempool.
/// 3. Idempotency. Every address is deterministic, so "did I already do this" is a code-size check
///    rather than a database question.
///
/// This contract is immutable and permanent per chain: its address is an input to every CREATE2
/// address it produces, so redeploying it renames every launch the network has ever predicted.
///
/// It keeps the liquidity it seeds, and with it the pool's LP fees, at whatever fee the hook sets:
/// anyone can claim a launch's fees, which split between its requester and the network (`PoolFees`).
contract LaunchFactory is IUnlockCallback, PoolFees {
    using SafeERC20 for IERC20;

    error NotDeployer();
    error AlreadyLaunched(uint64 launchNumber);
    error HookAddressMismatch(address predicted, uint160 wanted, uint160 got);
    error DeploymentFailed();
    error SupplyMismatch(uint256 expected, uint256 held);
    error InvalidPoolShare(uint16 poolBps);
    error RemainderRecipientMissing();
    error PoolShareExceeded(uint256 allowed, uint256 taken);
    error NotPoolManager();
    error CurrencyNotSorted();
    error NoLiquiditySeeded();
    error InitializationCallbackRequired();
    error PairedCurrencySpent(uint256 before, uint256 afterSeed);

    event Launched(
        uint64 indexed launchNumber,
        address indexed token,
        address indexed hook,
        address distributor,
        uint128 liquiditySeeded
    );

    /// @notice Everything one launch needs, assembled off chain from an attestation and a policy.
    /// @dev The technical half comes from the manifest and the attestation; the economic half comes
    /// from a policy row no model ever writes. Nothing here is derived on chain from the other, which
    /// is deliberate: the contract's job is to refuse a combination that does not add up, not to
    /// pick one.
    struct LaunchParams {
        uint64 launchNumber;
        bytes32 kind;
        /// @dev Creation code with constructor arguments already appended. The verifier attested the
        /// code without arguments; the deployer appends them and this recomputes what it deploys.
        bytes tokenCreationCode;
        bytes hookCreationCode;
        /// @dev Mined off chain until the resulting address carries exactly `hookFlags`.
        bytes32 hookSalt;
        uint160 hookFlags;
        /// @dev The whole supply, which the token must mint to this factory in its constructor.
        uint256 totalSupply;
        /// @dev Share of the whole supply the pool may take, the requester's choice within its 90%.
        /// The seed is rolled back if it takes more.
        uint16 poolBps;
        /// @dev Receives what the swarm and the pool leave: the requester's wallet, or zero for the
        /// chain's treasury (`LaunchFees.treasury()`), as for a launch nobody paid for.
        address remainderTo;
        bytes32 merkleRoot;
        uint64 contributorLockSeconds;
        uint64 sweepDelaySeconds;
        /// @dev The other side of the pair. Must sort below or above the launched token; the factory
        /// orders the key itself rather than trusting the caller to.
        Currency pairedCurrency;
        uint24 fee;
        int24 tickSpacing;
        uint160 sqrtPriceX96;
        int24 tickLower;
        int24 tickUpper;
        uint128 liquidity;
        LaunchRegistry.Launch record;
        uint256[] agentIds;
        /// @dev Who shares the pool's LP fees with the network: the wallet that paid for the launch, or zero.
        address requester;
    }

    /// @notice The swarm's share of every launch's supply: a constant, not a parameter. The other 90%
    /// is the requester's: `poolBps` of the supply seeds the pool, the rest goes to `remainderTo`.
    uint16 public constant SWARM_BPS = 1000;

    IPoolManager public immutable poolManager;
    LaunchRegistry public immutable registry;
    /// @notice The one address allowed to launch. It holds the key that spends; this holds nothing.
    address public immutable deployer;

    /// @dev Set for the duration of one `unlock`, so the callback knows what it is settling.
    struct Seeding {
        PoolKey key;
        int24 tickLower;
        int24 tickUpper;
        uint128 liquidity;
        address token;
    }

    constructor(IPoolManager poolManager_, address deployer_, LaunchFees fees_) PoolFees(fees_) {
        poolManager = poolManager_;
        deployer = deployer_;
        // Created here rather than passed in, so that pairing the two is not a step anyone has to
        // remember to get right. The registry takes writes from this factory and from nothing else,
        // and it has no owner: there is no privileged action on a record that cannot be revised.
        registry = new LaunchRegistry(address(this));
    }

    /// @notice Runs one launch, or reverts having done nothing.
    function launch(LaunchParams calldata params)
        external
        returns (address token, address hook, address distributor)
    {
        if (msg.sender != deployer) revert NotDeployer();
        if (registry.isRecorded(params.launchNumber)) revert AlreadyLaunched(params.launchNumber);
        // Before this transaction the hook has no code, so an initialize callback cannot succeed.
        // Its deployment and pool initialization share this transaction; outsiders cannot interleave.
        if ((params.hookFlags & (HookFlags.BEFORE_INITIALIZE | HookFlags.AFTER_INITIALIZE)) == 0) {
            revert InitializationCallbackRequired();
        }

        uint16 requesterBps = 10_000 - SWARM_BPS;
        if (params.poolBps == 0 || params.poolBps > requesterBps) revert InvalidPoolShare(params.poolBps);
        if (params.remainderTo == address(this)) revert RemainderRecipientMissing();

        token = _deploy(params.tokenCreationCode, _launchSalt(params.launchNumber));
        hook = _deploy(params.hookCreationCode, params.hookSalt);

        // The pool manager checks this too and reverts on `initialize`. Checking it here costs one
        // comparison and turns an opaque revert deep inside v4 into a named error naming both sides.
        if (!HookFlags.matches(hook, params.hookFlags)) {
            revert HookAddressMismatch(hook, params.hookFlags & HookFlags.ALL, HookFlags.flagsOf(hook));
        }

        // The token must mint its whole supply to whoever deployed it, which is this contract. A
        // token that minted somewhere else would leave the splits below silently short, so the
        // supply is checked as well as the balance: holding `totalSupply` proves nothing about a
        // second mint to another wallet.
        uint256 held = IERC20(token).balanceOf(address(this));
        if (held != params.totalSupply || IERC20(token).totalSupply() != params.totalSupply) {
            revert SupplyMismatch(params.totalSupply, held);
        }

        distributor = address(
            new MerkleDistributor{salt: _launchSalt(params.launchNumber)}(
                IERC20(token), address(this), fees, params.sweepDelaySeconds
            )
        );

        // The swarm's tenth, whole, to the contributors' distributor.
        uint256 contributorPool = (params.totalSupply * SWARM_BPS) / 10_000;
        IERC20(token).safeTransfer(distributor, contributorPool);
        // The factory opens this one round and can open no other; the distributor answers to the
        // chain's treasury from here on, and nobody can sweep it before its delay is up.
        MerkleDistributor(distributor).openRound(params.merkleRoot, contributorPool, params.contributorLockSeconds);

        PoolKey memory key = _seedRequesterPool(params, token, hook);
        _openPosition(params.launchNumber, key, params.tickLower, params.tickUpper, params.requester);
        _record(params, token, hook, distributor);

        emit Launched(params.launchNumber, token, hook, distributor, params.liquidity);
    }

    /// @dev Creates and seeds the pool with at most the requester's pool share, and sends what the
    /// swarm and the pool leave to the requester. The balance is read around the seed on purpose:
    /// what the pool took is the honest measure of its share. The seed's external calls cannot
    /// re-enter a launch (only the deployer launches, and `unlockCallback` answers only the pool
    /// manager), so the reading is not attackable.
    // slither-disable-start reentrancy-balance
    function _seedRequesterPool(LaunchParams calldata params, address token, address hook) private returns (PoolKey memory key) {
        key = _poolKey(token, hook, params);
        // The seed is the launched token only. Anything this factory holds in the paired currency
        // is fees owed to other requesters and the network (`PoolFees`), so the seed must not spend
        // it — whether a hook returns a delta, moves the empty pool's price from its initialize
        // callback, or the range simply straddles the price. Read before `initialize`, because the
        // hook's initialize callback is the first code that could move it.
        uint256 pairedBefore = params.pairedCurrency.balanceOfSelf();
        poolManager.initialize(key, params.sqrtPriceX96);
        if (params.liquidity == 0) revert NoLiquiditySeeded();
        uint256 before = IERC20(token).balanceOf(address(this));
        poolManager.unlock(
            abi.encode(
                Seeding({
                    key: key,
                    tickLower: params.tickLower,
                    tickUpper: params.tickUpper,
                    liquidity: params.liquidity,
                    token: token
                })
            )
        );
        uint256 taken = before - IERC20(token).balanceOf(address(this));
        uint256 allowed = (params.totalSupply * params.poolBps) / 10_000;
        if (taken > allowed) revert PoolShareExceeded(allowed, taken);
        uint256 pairedAfter = params.pairedCurrency.balanceOfSelf();
        if (pairedAfter < pairedBefore) revert PairedCurrencySpent(pairedBefore, pairedAfter);
        uint256 remainder = IERC20(token).balanceOf(address(this));
        if (remainder > 0) IERC20(token).safeTransfer(params.remainderTo == address(0) ? fees.treasury() : params.remainderTo, remainder);
    }
    // slither-disable-end reentrancy-balance

    /// @notice Settles the liquidity this factory just added.
    /// @dev v4 hands back a signed delta per currency: negative is owed to the pool, positive is owed
    /// to us. Both directions are handled rather than only the expected one — a hook that returns a
    /// delta can turn "we owe the pool" into "the pool owes us", and an implementation that only
    /// knew how to pay would strand tokens inside the manager.
    function unlockCallback(bytes calldata data) external override returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        if (_claiming()) return _collect(data);

        Seeding memory seeding = abi.decode(data, (Seeding));

        (BalanceDelta delta,) = poolManager.modifyLiquidity(
            seeding.key,
            ModifyLiquidityParams({
                tickLower: seeding.tickLower,
                tickUpper: seeding.tickUpper,
                liquidityDelta: int256(uint256(seeding.liquidity)),
                salt: bytes32(0)
            }),
            ""
        );

        _settle(seeding.key.currency0, delta.amount0());
        _settle(seeding.key.currency1, delta.amount1());

        return "";
    }

    function _manager() internal view override returns (IPoolManager) {
        return poolManager;
    }

    /// @dev Pays what is owed, or takes what is owed to us. Zero is neither.
    function _settle(Currency currency, int128 amount) private {
        if (amount < 0) {
            uint256 due = uint256(uint128(-amount));
            poolManager.sync(currency);
            if (currency.isAddressZero()) {
                poolManager.settle{value: due}();
            } else {
                IERC20(Currency.unwrap(currency)).safeTransfer(address(poolManager), due);
                poolManager.settle();
            }
        } else if (amount > 0) {
            poolManager.take(currency, address(this), uint256(uint128(amount)));
        }
    }

    /// @dev v4 requires the pair sorted by address, and the caller does not get to decide the order.
    /// The hook is the one this transaction just deployed — not an address the caller supplies, which
    /// would let a launch attest one hook and pool against another.
    function _poolKey(address token, address hook, LaunchParams calldata params)
        private
        pure
        returns (PoolKey memory)
    {
        Currency launched = Currency.wrap(token);
        Currency paired = params.pairedCurrency;

        (Currency currency0, Currency currency1) =
            Currency.unwrap(launched) < Currency.unwrap(paired) ? (launched, paired) : (paired, launched);

        if (Currency.unwrap(currency0) >= Currency.unwrap(currency1)) revert CurrencyNotSorted();

        return PoolKey({
            currency0: currency0,
            currency1: currency1,
            fee: params.fee,
            tickSpacing: params.tickSpacing,
            hooks: IHooks(hook)
        });
    }

    function _record(LaunchParams calldata params, address token, address hook, address distributor)
        private
    {
        LaunchRegistry.Artifact[] memory artifacts = new LaunchRegistry.Artifact[](3);
        artifacts[0] = LaunchRegistry.Artifact("token", "token", token);
        artifacts[1] = LaunchRegistry.Artifact("hook", "hook", hook);
        artifacts[2] = LaunchRegistry.Artifact("distributor", "distributor", distributor);

        LaunchRegistry.Launch memory entry = params.record;
        entry.launchNumber = params.launchNumber;
        entry.kind = params.kind;

        registry.record(entry, artifacts, params.agentIds);
    }

    /// @dev CREATE2 so every address is knowable before anything is sent, which is what makes a
    /// crashed deployer recoverable rather than expensive.
    function _deploy(bytes memory creationCode, bytes32 salt) private returns (address deployed) {
        assembly ("memory-safe") {
            deployed := create2(0, add(creationCode, 0x20), mload(creationCode), salt)
        }
        if (deployed == address(0)) revert DeploymentFailed();
    }

    /// @dev The salt for everything a launch deploys that nobody has to mine: the token and the
    /// distributor. The hook's salt is mined off chain for its flags and taken exactly as given.
    function _launchSalt(uint64 launchNumber) private pure returns (bytes32) {
        return bytes32(uint256(launchNumber));
    }

    /// @notice The distributor's creation-code hash, so the deployer can report the distributor as an
    /// artifact the way the project factory's launches report theirs.
    function distributorCreationCodeHash() external pure returns (bytes32) {
        return keccak256(type(MerkleDistributor).creationCode);
    }

    /// @notice Where a launch's token will land, before it exists.
    /// @dev The whole idempotency story: the deployer predicts, checks for code, and skips a launch
    /// that already happened rather than paying for it twice.
    function predictToken(uint64 launchNumber, bytes calldata tokenCreationCode)
        external
        view
        returns (address)
    {
        return _predict(_launchSalt(launchNumber), tokenCreationCode);
    }

    /// @notice Where a launch's hook will land, for the salt the deployer mined.
    /// @dev The salt is taken exactly as `launch` takes it. One `predict` for both used to read a
    /// zero salt as "none given, use the launch number" — a fine default for a token and a wrong
    /// answer for a hook: the miner counts up from zero, so zero is a salt a launch can really carry,
    /// and it was the one value for which the prediction and the deployment disagreed.
    function predictHook(bytes calldata hookCreationCode, bytes32 hookSalt)
        external
        view
        returns (address)
    {
        return _predict(hookSalt, hookCreationCode);
    }

    /// @dev CREATE2 as the EVM computes it, with this factory as the deployer.
    function _predict(bytes32 salt, bytes calldata creationCode) private view returns (address) {
        return address(
            uint160(
                uint256(
                    keccak256(
                        abi.encodePacked(bytes1(0xff), address(this), salt, keccak256(creationCode))
                    )
                )
            )
        );
    }

    receive() external payable {}
}

src/LaunchRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title The public record of everything this network has launched
/// @notice One entry per launch: what was deployed, from which tree, attested by whom, and by which
/// agents. The off-chain `launches` table stays the operational source of truth; this is the
/// tamper-evident public one, and it is what makes the provenance story legible to someone who does
/// not trust our API.
///
/// @dev Deliberately generic. Nothing in it says "hook": artifacts carry a role rather than a
/// column, so a launch kind that deploys something else entirely is a new recipe rather than a new
/// registry. `writer` is the only address that may record, and it is set once at construction to the
/// factory — a registry anyone could write to is a registry that records nothing.
contract LaunchRegistry {
    struct Artifact {
        /// @dev `token`, `hook`, `distributor`, `other` — matched to `launch_artifacts.role`.
        bytes32 role;
        bytes32 name;
        address addr;
    }

    struct Launch {
        bytes32 kind;
        /// @dev Position in the network's launch history, carried over from the job that produced it.
        uint64 launchNumber;
        uint64 recordedAt;
        /// @dev Git commit of the delivered tree, and the hash of the document that attested it.
        bytes32 sourceCommit;
        bytes32 manifestHash;
        bytes32 attestationHash;
        /// @dev Ed25519 public key of the verifier that signed the attestation.
        bytes32 verifierKey;
        string sourceRepoUrl;
    }

    error NotWriter();
    error AlreadyRecorded(uint64 launchNumber);
    error NoArtifacts();

    event LaunchRecorded(
        uint64 indexed launchNumber,
        bytes32 indexed kind,
        bytes32 sourceCommit,
        bytes32 attestationHash,
        address[] artifacts,
        uint256[] agentIds
    );

    /// @notice The only address that may record a launch. Immutable, and it is the factory.
    address public immutable writer;

    mapping(uint64 launchNumber => Launch) private _launches;
    mapping(uint64 launchNumber => Artifact[]) private _artifacts;
    mapping(uint64 launchNumber => uint256[]) private _agentIds;

    uint64 public count;

    constructor(address writer_) {
        writer = writer_;
    }

    /// @notice Records one launch, once.
    /// @dev Re-recording is refused rather than overwritten. This is the public record; a version of
    /// it that the writer could quietly revise would be worth exactly as much as our word alone,
    /// which is the thing it exists to not require.
    function record(
        Launch calldata launch,
        Artifact[] calldata artifacts,
        uint256[] calldata agentIds
    ) external {
        if (msg.sender != writer) revert NotWriter();
        if (_launches[launch.launchNumber].recordedAt != 0) revert AlreadyRecorded(launch.launchNumber);
        if (artifacts.length == 0) revert NoArtifacts();

        _launches[launch.launchNumber] = launch;
        _launches[launch.launchNumber].recordedAt = uint64(block.timestamp);

        address[] memory addresses = new address[](artifacts.length);
        for (uint256 i = 0; i < artifacts.length; i++) {
            _artifacts[launch.launchNumber].push(artifacts[i]);
            addresses[i] = artifacts[i].addr;
        }

        for (uint256 i = 0; i < agentIds.length; i++) {
            _agentIds[launch.launchNumber].push(agentIds[i]);
        }

        count++;

        emit LaunchRecorded(
            launch.launchNumber,
            launch.kind,
            launch.sourceCommit,
            launch.attestationHash,
            addresses,
            agentIds
        );
    }

    function launchOf(uint64 launchNumber) external view returns (Launch memory) {
        return _launches[launchNumber];
    }

    function artifactsOf(uint64 launchNumber) external view returns (Artifact[] memory) {
        return _artifacts[launchNumber];
    }

    function agentsOf(uint64 launchNumber) external view returns (uint256[] memory) {
        return _agentIds[launchNumber];
    }

    /// @notice Whether a launch number has been recorded. Cheaper than reading the whole struct.
    function isRecorded(uint64 launchNumber) external view returns (bool) {
        return _launches[launchNumber].recordedAt != 0;
    }
}

src/MerkleDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {MerkleProof} from "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {LaunchFees} from "./LaunchFees.sol";

/// @title Contributor allocations for one launch
/// @notice Funded inside the launch transaction with the contributor pool, and claimed rather than
/// pushed. On mainnet that is the difference between one transaction per launch and one per
/// contributor; it also means a dead or wrong address costs nothing, and unclaimed value is
/// recoverable rather than burnt.
///
/// @dev Rounds rather than a single root, so a remediation job can be paid later without deploying a
/// second contract. Each round has its own root and its own funding; a leaf is `(account, amount)`
/// and carries no index, because OpenZeppelin's `StandardMerkleTree` double-hashes and sorts pairs,
/// so a leaf is identified by its content. One fewer thing for the two sides to agree on, on the
/// path where disagreeing means a contributor cannot be paid.
///
/// Nobody owns it. The factory that made it opens its first round in the launch transaction and
/// can open no other; later rounds are the treasury's, and the treasury is whatever the chain's
/// `LaunchFees` names when it is asked, so moving it there moves it here. Unclaimed value goes to
/// that treasury once a round's sweep delay is up, and anyone may send it: it can go nowhere else.
contract MerkleDistributor is ReentrancyGuard {
    using SafeERC20 for IERC20;

    error NotOpener();
    error AlreadyClaimed();
    error InvalidProof();
    error NoSuchRound();
    error StillLocked(uint64 unlocksAt);
    error SweepTooEarly(uint64 sweepableAt);
    error EmptyRoot();
    error RoundClosed();
    error InsufficientFunding();
    error InsufficientRoundBalance();

    event RoundOpened(uint256 indexed round, bytes32 root, uint256 funded, uint64 unlocksAt);
    event Claimed(uint256 indexed round, address indexed account, uint256 amount);
    event Swept(address indexed to, uint256 amount);

    struct Round {
        bytes32 root;
        uint256 funded;
        uint256 claimed;
        /// @dev Contributor allocations vest as a cliff. A fresh launch whose worker allocations are
        /// instantly liquid prices itself down at birth, which costs the contributors it was meant
        /// to pay.
        uint64 unlocksAt;
    }

    IERC20 public immutable token;
    /// @notice The factory that made it: it may open the first round, and nothing after.
    address public immutable opener;
    /// @notice The chain's fee settings, which name the treasury.
    LaunchFees public immutable fees;
    /// @notice How long after a round opens before what is left may be swept. Never before the round
    /// unlocks, whatever this says: see `sweep`.
    uint64 public immutable sweepDelay;

    Round[] private _rounds;
    mapping(uint256 round => mapping(address account => bool)) public claimed;
    mapping(uint256 round => uint64) public openedAt;
    mapping(uint256 round => bool) public swept;
    /// @notice Tokens still owed by all open rounds. A new round must have its own funding.
    uint256 public reserved;

    constructor(IERC20 token_, address opener_, LaunchFees fees_, uint64 sweepDelay_) {
        token = token_;
        opener = opener_;
        fees = fees_;
        sweepDelay = sweepDelay_;
    }

    /// @notice Where unclaimed value goes, and who may open a later round: the chain's treasury now.
    function treasury() public view returns (address) {
        return fees.treasury();
    }

    /// @notice Opens a round against tokens this contract already holds.
    /// @dev Funding is checked rather than pulled: the launch transaction transfers the contributor
    /// pool in and opens the round in the same call, and a distributor that could pull would need an
    /// allowance from something that has one.
    function openRound(bytes32 root, uint256 funded, uint64 lockSeconds)
        external
        nonReentrant
        returns (uint256 round)
    {
        if (msg.sender != treasury() && (msg.sender != opener || _rounds.length != 0)) revert NotOpener();
        if (root == bytes32(0)) revert EmptyRoot();
        if (token.balanceOf(address(this)) < reserved + funded) revert InsufficientFunding();
        reserved += funded;

        round = _rounds.length;
        _rounds.push(
            Round({
                root: root,
                funded: funded,
                claimed: 0,
                unlocksAt: uint64(block.timestamp) + lockSeconds
            })
        );
        openedAt[round] = uint64(block.timestamp);

        emit RoundOpened(round, root, funded, _rounds[round].unlocksAt);
    }

    /// @notice Claims one allocation.
    /// @dev Anyone may submit the proof, but the tokens only ever go to the account in the leaf. That
    /// lets us pay the gas for a contributor who has none without being able to redirect what they
    /// are owed.
    function claim(uint256 round, address account, uint256 amount, bytes32[] calldata proof) external nonReentrant {
        if (round >= _rounds.length) revert NoSuchRound();
        Round storage current = _rounds[round];

        if (swept[round]) revert RoundClosed();
        if (block.timestamp < current.unlocksAt) revert StillLocked(current.unlocksAt);
        if (claimed[round][account]) revert AlreadyClaimed();

        // Double hashing is what makes a leaf unforgeable as an internal node — the shape
        // OpenZeppelin's StandardMerkleTree produces, and what our off-chain tree builds.
        bytes32 leaf = keccak256(bytes.concat(keccak256(abi.encode(account, amount))));
        if (!MerkleProof.verifyCalldata(proof, current.root, leaf)) revert InvalidProof();
        if (amount > current.funded - current.claimed) revert InsufficientRoundBalance();

        claimed[round][account] = true;
        current.claimed += amount;
        reserved -= amount;

        token.safeTransfer(account, amount);
        if (token.balanceOf(address(this)) < reserved) revert InsufficientFunding();
        emit Claimed(round, account, amount);
    }

    /// @notice Sends what a round's claimants never took to the treasury. Anyone may call it once the
    /// round's delay is up: the tokens can go only to the treasury `LaunchFees` names at that moment.
    /// @dev `block.timestamp` is compared here and in `claim`, which the linter flags. It is the
    /// right clock for both: a validator can move it by seconds, and these windows are a six-month
    /// lock and a one-year sweep delay. Block numbers would be worse — they drift against wall time,
    /// and a lock a contributor was told lasts six months should last six months.
    /// @dev Deliberately late and deliberately to one address, the network's treasury. Unclaimed value that can never be
    /// recovered is a slow leak; unclaimed value that can be recovered early is a reason not to
    /// trust the distributor at all.
    /// @dev Never before the round unlocks, whichever of the two clocks runs later. The delay counts
    /// from the round opening and is one number the deployer sets for every launch; the lock is
    /// another, set per launch by policy; nothing checks one against the other, and a lock longer
    /// than the delay would otherwise let the treasury empty a round no contributor could yet touch.
    /// Waited out here rather than refused in `openRound`: a long lock is a legitimate choice and
    /// not a mistake, and refusing it would revert the whole launch over a constant somebody has to
    /// go and change, when the only correct answer to it is to wait.
    function sweep(uint256 round) external nonReentrant returns (uint256 amount) {
        if (round >= _rounds.length) revert NoSuchRound();
        if (swept[round]) revert RoundClosed();
        Round storage current = _rounds[round];

        uint64 sweepableAt = openedAt[round] + sweepDelay;
        uint64 unlocksAt = current.unlocksAt;
        if (unlocksAt > sweepableAt) sweepableAt = unlocksAt;
        if (block.timestamp < sweepableAt) revert SweepTooEarly(sweepableAt);

        // Close the old proofs before paying out, and leave every other round's tokens in place.
        amount = current.funded - current.claimed;
        swept[round] = true;
        reserved -= amount;
        address to = treasury();
        if (amount > 0) token.safeTransfer(to, amount);
        if (token.balanceOf(address(this)) < reserved) revert InsufficientFunding();
        emit Swept(to, amount);
    }

    function roundCount() external view returns (uint256) {
        return _rounds.length;
    }

    function roundOf(uint256 round) external view returns (Round memory) {
        if (round >= _rounds.length) revert NoSuchRound();
        return _rounds[round];
    }
}

